CREATE TABLE signals(signal_id uuid PRIMARY KEY,target_id uuid NOT NULL,account_snapshot_id uuid NOT NULL,pricing_snapshot_id uuid NOT NULL,decision_at timestamptz NOT NULL,valid_for_date date NOT NULL,expires_at timestamptz NOT NULL,status text NOT NULL,input_hash char(64) UNIQUE NOT NULL,content_hash char(64) NOT NULL,account_reconciled boolean NOT NULL,oldest_price_at timestamptz NOT NULL,max_price_age_seconds integer NOT NULL,reprice_threshold numeric NOT NULL,risk_result_id uuid,risk_decision text,CHECK(expires_at>decision_at));
CREATE TABLE signal_components(component_id uuid PRIMARY KEY,signal_id uuid NOT NULL REFERENCES signals,strategy_kind text NOT NULL,run_id uuid NOT NULL,instrument_id uuid,state text NOT NULL,weight_contribution numeric NOT NULL,reason_codes jsonb NOT NULL);
CREATE TABLE recommendations(recommendation_id uuid PRIMARY KEY,signal_id uuid NOT NULL REFERENCES signals,instrument_id uuid NOT NULL REFERENCES instruments,side text NOT NULL,target_weight numeric NOT NULL,current_weight numeric NOT NULL,delta_weight numeric NOT NULL,quantity integer NOT NULL CHECK(quantity>0),limit_price numeric NOT NULL CHECK(limit_price>0),estimated_fee numeric NOT NULL CHECK(estimated_fee>=0),reason_codes jsonb NOT NULL,status text NOT NULL,approved_quantity integer NOT NULL,handed_off_quantity integer NOT NULL,version integer NOT NULL,UNIQUE(signal_id,instrument_id),CHECK(handed_off_quantity>=0 AND handed_off_quantity<=approved_quantity AND approved_quantity<=quantity));
CREATE TABLE recommendation_risk_refs(signal_id uuid PRIMARY KEY REFERENCES signals,risk_result_id uuid NOT NULL,decision text NOT NULL);
CREATE TABLE approval_decisions(approval_id uuid PRIMARY KEY,recommendation_id uuid NOT NULL REFERENCES recommendations,decision_id uuid UNIQUE NOT NULL,kind text NOT NULL,quantity integer NOT NULL,reason text NOT NULL,operator_id text NOT NULL,decided_at timestamptz NOT NULL,expected_version integer NOT NULL);
CREATE TABLE signal_supersessions(supersession_id uuid PRIMARY KEY,old_signal_id uuid UNIQUE NOT NULL REFERENCES signals,new_signal_id uuid NOT NULL REFERENCES signals,reason text NOT NULL,superseded_at timestamptz NOT NULL);
CREATE TABLE signal_events(event_id uuid PRIMARY KEY,event_type text NOT NULL,signal_id uuid NOT NULL,occurred_at timestamptz NOT NULL,payload jsonb NOT NULL);
